FLASH_MEM_UPDATE:  ; EF4F6F
	PUSH QIZ
	CALL Check_for_Floppy_Disk_Change
	CP L 0
	JRL Z flash_update__not_today
	CALR LABEL_EF4241
	CALR Detect_Disk_Type
	LD QIZH L
	CALL Get_Area_Region_Code
	CP L 4
	JR Z LABEL_EF4FE4
	CALL LABEL_EF3D0E
	CP XHL, 0xffffffff
	JR Z LABEL_EF4FE4
	CP QIZH 6  ; Is it "HD-AEPRG DATA FILE"?
	JR Z LABEL_EF4FE4  ; yes, it is.
	PUSH 0x0008
	PUSH 0x0002
	LD XWA, Bitmap_1bit_Flash_Memory_Update  ; "Flash Memory Update"
	LD BC, 0x0030
	LD DE, 0x0050
	CALL Draw_FlashMemUpdate_message_bitmap
	LD A QIZH
	EXTZ WA
	CALR Erase_and_Burn____when_disk_is_valid
	PUSH 0x0008
	PUSH 0x0001
	LD XWA, Bitmap_1bit_Completed  ; "Completed!"
	LD BC, 0x0030
	LD DE, 0x00a0
	CALL Draw_FlashMemUpdate_message_bitmap
	PUSH 0x0008
	PUSH 0x0001
	LD XWA, Bitmap_1bit_Turn_On_AGAIN  ; "Turn On AGAIN !!"
	LD BC, 0x0030
	LD DE, 0x00c8
	CALL Draw_FlashMemUpdate_message_bitmap

LABEL_EF4FE4:
	LD WA 2
	CALL LABEL_EF379A
	CP HL, 0xffff
	JR Z flash_update__not_today
	CP QIZH 6  ; Is it "HD-AEPRG DATA FILE"?
	JR NZ flash_update__not_today
	PUSH 0x0008
	PUSH 0x0002
	LD XWA, Bitmap_1bit_Flash_Memory_Update  ; "Flash Memory Update"
	LD BC, 0x0030
	LD DE, 0x0050
	CALL Draw_FlashMemUpdate_message_bitmap
	LD A QIZH
	EXTZ WA
	CALR Erase_and_Burn____when_disk_is_valid
	PUSH 0x0008
	PUSH 0x0001
	LD XWA, Bitmap_1bit_Completed  ; "Completed!"
	LD BC, 0x0030
	LD DE, 0x00a0
	CALL Draw_FlashMemUpdate_message_bitmap
	PUSH 0x0008
	PUSH 0x0001
	LD XWA, Bitmap_1bit_Turn_On_AGAIN  ; "Turn On AGAIN !!"
	LD BC, 0x0030
	LD DE, 0x00c8
	CALL Draw_FlashMemUpdate_message_bitmap

flash_update__not_today:  ; EF503C
	POP QIZ
	RET

Draw_FlashMemUpdate_message_bitmap:  ; EF5040
	DEC 4 XSP
	PUSH IZ
	LD HL BC
	LD (XSP + 0x02), XWA
	LD IY HL
	LD IX DE
	INC 1 IX
	LD IZ 0

LABEL_EF5050:
	LD WA IZ
	EXTZ XWA
	DIV WA, 0x001c ; 28 bytes = 224 pixels de largura da imagem a ser desenhada
	LD WA QWA
	CP WA 0
	JR NZ LABEL_EF5063
	LD IY HL ; IY = coordanada X do canto esquerdo da imagem a ser desenhada
	DEC 1 IX

LABEL_EF5063:
	LD QHL 0

LABEL_EF5066:
	LD DE IZ
	EXTZ XDE
	ADD XDE (XSP + 0x02)
	LDA XWA, 0xE36A       ; table of bit masks (equivalent to 0x1044 on boot "table_data" rom)
	LD BC QHL
	EXTZ XBC
	ADD XBC, XWA  ; indexing bit masks with value of QHL
	LD A, (XBC)
	AND A, (XDE)  ; here XDE points at one of the bytes of the image we're drawing and we select the bit we need
	LD QIXL A
	LD DE IX
	EXTZ XDE
	LDA XBC 0x043C00   ; aparentemente isso é um buffer offscreen

Set_XWA_to_320_times_XDE:
	LD XWA XDE
	SLL 2, XWA
	ADD XWA XDE
	SLL 6, XWA
	CP QIXL 0
	JR Z LABEL_EF50AA
	LD DE IY
	INC 1 IY
	EXTZ XDE
	ADD XWA XDE
	LD XDE XBC
	ADD XDE, XWA
	LD A, (XSP + 0x0a)
	LD (XDE), A
	JR T LABEL_EF50BB

LABEL_EF50AA:
	LD DE IY    
	INC 1 IY
	EXTZ XDE
	ADD XWA XDE   ; XWA = 320*y + x
	LD XDE XBC
	ADD XDE, XWA   ; XDE = offscreen_buffer[320*y + x]
	LD A, (XSP + 0x0c)
	LD (XDE), A

LABEL_EF50BB:
	INC 1 QHL
	CP QHL, 0x0008
	JR C LABEL_EF5066
	INC 1 IZ
	CP IZ, 0x0268     ; 28 bytes (224 pixels/line) * 22 lines = 0x268 bytes 
	JR C LABEL_EF5050
	LDA XWA, 0x1A0000 ; memoria de video
	LD DE, 0x9600 ; 320x120 words = 320x240 pixels
	CALL Copy_DE_words_from_XBC_to_XWA  ; <-- "blit-screen"
	POP IZ
	INC 4 XSP
	RETD, 0x0004

LABEL_EF50DF:
	DEC 6 XSP
	PUSH XIZ
	LD (XSP + 0x06), E
	LD (XSP + 0x08), WA
	LD IX BC
	LD (XSP + 0x04), BC
	ADD (XSP + 0x04), 0x000c
	CP IX (XSP + 0x04)
	JR NC LABEL_EF513D

LABEL_EF50F7:
	LD IY (XSP + 0x08)
	LD BC IY
	INC 6 BC
	CP IY BC
	JR NC LABEL_EF5136

LABEL_EF5102:
	LD DE IY
	EXTZ XDE
	LD WA IX
	EXTZ XWA
	LD XHL XWA
	SLL 2, XHL
	ADD XHL XWA
	SLL 6, XHL
	ADD XHL XDE
	SRL 1, XHL
	ADD XHL XHL
	LD XIZ, 0x001a0000
	ADD XIZ XHL
	LD A, (XSP + 0x06)
	EXTZ WA
	LD DE WA
	SLL 8, DE
	OR WA DE
	LD (XIZ), WA
	INC 2 IY
	CP IY BC
	JR C LABEL_EF5102

LABEL_EF5136:
	INC 1 IX
	CP IX (XSP + 0x04)
	JR C LABEL_EF50F7

LABEL_EF513D:
	POP XIZ
	INC 6 XSP
	RET

Write_VGA_Register:
	LD DE 0

LABEL_EF5143:
	INC 1 DE
	CP DE, 0x0100
	JR C LABEL_EF5143
	EXTZ XWA
	LD XDE, 0x00170000
	ADD XDE, XWA
	LD (XDE), C
	RET

Read_VGA_Register:
	EXTZ XWA
	LD XBC, 0x00170000
	ADD XBC, XWA
	LD L (XBC)
	RET

MACRO VGA_WRITE(register, value)
	LD WA, 0x#register
	LD BC, 0x#value
	CALR Write_VGA_Register
ENDMACRO

MACRO PALLETE_WRITE(red, green, blue)
	LD WA, 0x3c9
	LD BC, 0x#red
	CALR Write_VGA_Register
	LD BC, 0x#green
	CALR Write_VGA_Register
	LD BC, 0x#blue
	CALR Write_VGA_Register
ENDMACRO

MACRO VGA_ATTRIBUTE(field, value)
	VGA_WRITE(3c0, #field)
	VGA_WRITE(3c0, #value)
ENDMACRO

MACRO VGA_SEQUENCER(field, value)
	VGA_WRITE(3c4, #field)
	VGA_WRITE(3c5, #value)
ENDMACRO

MACRO VGA_GFX_CONTROLLER(field, value)
	VGA_WRITE(3ce, #field)
	VGA_WRITE(3cf, #value)
ENDMACRO

MACRO VGA_COLOR_CRTC(field, value)
	VGA_WRITE(3d4, #field)
	VGA_WRITE(3d5, #value)
ENDMACRO


