Some_VGA_setup:
	VGA_WRITE(3c3, 01)  ; Global enable
	VGA_WRITE(3c2, e3)  ; Misc. Output (select 25 MHz dot clock & 60 Hz scanning rate)

	VGA_SEQUENCER(00, 00)  ; Reset
	VGA_SEQUENCER(01, 21)  ; Clocking Mode (screen off)
	VGA_SEQUENCER(00, 03)  ; Reset
	VGA_SEQUENCER(02, 0f)  ; Map Mask (enable writes to all four planes)
	VGA_SEQUENCER(03, 00)  ; Character Map Select
	VGA_SEQUENCER(04, 06)  ; Memory Mode

	VGA_GFX_CONTROLLER(01, 00)  ; Enable Set/Reset
	VGA_GFX_CONTROLLER(03, 00)  ; Data Rotate
	VGA_GFX_CONTROLLER(04, 00)  ; Read Map Select
	VGA_GFX_CONTROLLER(05, 00)  ; Mode
	VGA_GFX_CONTROLLER(06, 01)  ; Misc.
	VGA_GFX_CONTROLLER(08, ff)  ; Bit Mask

	VGA_COLOR_CRTC(11, 00)  ; Vertical Retrace Low
	VGA_COLOR_CRTC(07, 10)  ; Overflow
	VGA_COLOR_CRTC(08, 00)  ; Preset Row Scan
	VGA_COLOR_CRTC(09, 40)  ; Max Scan Line
	VGA_COLOR_CRTC(0c, 00)  ; Start Address High
	VGA_COLOR_CRTC(0d, 00)  ; Start Address Low
	VGA_COLOR_CRTC(12, ef)  ; Vertical Display End
	VGA_COLOR_CRTC(13, 14)  ; Offset
	VGA_COLOR_CRTC(14, 00)  ; Underline Location
	VGA_COLOR_CRTC(17, e3)  ; Mode Control
	VGA_COLOR_CRTC(18, ff)  ; Line Compare

	VGA_WRITE(3da, ff)

    ; The colors below are the default EGA palette selection:
	; https://en.wikipedia.org/wiki/Enhanced_Graphics_Adapter#/media/File:EGA_Table.svg
	VGA_ATTRIBUTE(00, 00)  ; 000 000 + Palette Address Source (bit 5) = 0
	VGA_ATTRIBUTE(01, 01)  ; 000 001
	VGA_ATTRIBUTE(02, 02)  ; 000 010
	VGA_ATTRIBUTE(03, 03)  ; 000 011
	VGA_ATTRIBUTE(04, 04)  ; 000 100
	VGA_ATTRIBUTE(05, 05)  ; 000 101
	VGA_ATTRIBUTE(06, 14)  ; 010 100
	VGA_ATTRIBUTE(07, 07)  ; 000 111
	VGA_ATTRIBUTE(08, 38)  ; 111 000
	VGA_ATTRIBUTE(09, 39)  ; 111 001
	VGA_ATTRIBUTE(0a, 3a)  ; 111 010
	VGA_ATTRIBUTE(0b, 3b)  ; 111 011
	VGA_ATTRIBUTE(0c, 3c)  ; 111 100
	VGA_ATTRIBUTE(0d, 3d)  ; 111 101
	VGA_ATTRIBUTE(0e, 3e)  ; 111 110
	VGA_ATTRIBUTE(0f, 3f)  ; 111 111
	VGA_ATTRIBUTE(10, 01)  ; Mode Control
	VGA_ATTRIBUTE(11, 00)  ; Overscan Color
	VGA_ATTRIBUTE(12, 0f)  ; Color Plane Enable
	VGA_ATTRIBUTE(13, 00)  ; Horizontal Pixel Panning
	VGA_ATTRIBUTE(34, 00)  ; Color Select + Palette Address Source (bit 5) = 1

	VGA_SEQUENCER(06, 01)  ; (?)

	VGA_COLOR_CRTC(00, 65)  ; Horizontal Total
	VGA_COLOR_CRTC(01, 27)  ; Horizontal Display End
	VGA_COLOR_CRTC(04, 28)  ; Start Horizontal Retrace
	VGA_COLOR_CRTC(05, 29)  ; End Horizontal Retrace
	VGA_COLOR_CRTC(06, f3)  ; Vertical Total
	VGA_COLOR_CRTC(07, 00)  ; Overflow
	VGA_COLOR_CRTC(09, 00)  ; Maximum Scan Line
	VGA_COLOR_CRTC(10, f2)  ; Vertical Retrace Start
	VGA_COLOR_CRTC(11, 03)  ; Vertical Retrace End
	VGA_COLOR_CRTC(15, ef)  ; Start Vertical Blank
	VGA_COLOR_CRTC(16, f3)  ; End Vertical Blank

	VGA_SEQUENCER(08, 01)  ; (?)
	VGA_SEQUENCER(0d, 03)  ; (?)
	VGA_SEQUENCER(0f, 00)  ; (?)

	VGA_COLOR_CRTC(19, 00)  ; (?)
	VGA_COLOR_CRTC(1a, 10)  ; (?)

	VGA_SEQUENCER(07, 20)  ; Horizontal Character Counter Reset
	VGA_SEQUENCER(06, 00)  ; (?)

	VGA_COLOR_CRTC(11, 80)  ; Vertical Retrace End + "Protect Registers 0-7" enabled

	VGA_WRITE(3c6, ff)

	; Palette
  	VGA_WRITE(3c8, 0)
	PALLETE_WRITE(00, 00, 00)  ;  0: Black
	PALLETE_WRITE(0f, 0f, 0f)  ;  1: white
	PALLETE_WRITE(0f, 00, 00)  ;  2: red
	PALLETE_WRITE(00, 0f, 00)  ;  3: green
	PALLETE_WRITE(00, 00, 0f)  ;  4: blue
	PALLETE_WRITE(00, 0f, 0f)  ;  5: cyan
	PALLETE_WRITE(0f, 0f, 00)  ;  6: yellow
	PALLETE_WRITE(0f, 00, 0f)  ;  7: magenta
	PALLETE_WRITE(00, 00, 04)  ;  8: dark blue

	CALR LABEL_EF5163
	LD XWA, 0x00043c00
	LD BC, 0x0808
	LD DE, 0x9600
	CALL Fill_memory_at_XWA_with_DE_words_of_BC_value
	LDA XWA, 0x1A0000
	LD XBC, 0x00043c00
	LD DE, 0x9600
	CALL Copy_DE_words_from_XBC_to_XWA

	VGA_SEQUENCER(01, 01)  ; Clocking Mode (screen on)
	RET

