	RET


SOME_CPANEL_ROUTINE__FC3EF5:
	LD XHL, SomeCpanelData
	LD (XHL - 4), 0x0000
	LD (XHL - 8), 0x0000
	LD (XHL - 2), 0x0080

	LD XHL, SomeOtherCpanelData
	LD (XHL - 4), 0x0000
	LD (XHL - 8), 0x0000
	LD (XHL - 2), 0x0080

	LD A, 0x03 ; PF2=SCK0 Disabled, PF0=TxD0 and PF1=RxD0 (MIDI) 
	AND A, 0xaf ; PF6=SCK1 Disabled, PF4=TxD1 and PF5=RxD1 (Control Panel)
	LD (PFFC_VALUE), A
	LD (PFFC), A
	LD A, 0x15
	AND A, 0x8f
	LD (PFCR_VALUE), A
	LD (PFCR), A
	AND (PF), 0xbf ; PF bit 6 (SCLK1 | /CTS1) = 0
	LD A, 0x00
	LD (PEFC), A
	LD A, 0x46
	LD (PECR), A
	LD (SC1MOD), 0x00 ; serial clk: TO2 trigger
	                  ; serial transfer mode: I/O  transfer mode
	                  ; wake-up function: disable
	                  ; receive control: receive disable
	                  ; handshake function control: CTS disable
	LD (BR1CR), 0x14 ; Internal Clock T2 (16/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/16/4 = 250kHz
	LD (SC1CR), 0x01 ; Parity: odd
	                 ; Parity addition: disable
	                 ; clear all errors
	                 ; Data transmit/receive at SCLK1 rising edge
	                 ; I/O interface input clock: SCLK1 pin input
	LD (INTEAB), 0x07
	LD (INTCLR), 0x12 ; INTA Pin
	LD (INTES1), 0xff
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	OR (TAMOD), 0x10
	AND (TAMOD), 0xf7
	LD (CPANEL_UNUSED_1), 0x7d  ; This looks pointless...

	OR (CPANEL_SERIAL_FLAGS_A), 0x40 ; CP_Flags_A.6 = 1
	LD (CPANEL_STATE_0_TO_17), 0x00
	AND (CPANEL_SERIAL_FLAGS_A), 0xfc ; CP_Flags_A.10 = 00
	LD (CPANEL_INDEX_FOR_LEDS), 0x0000
	LD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), 0x0000
	LD (CPANEL_BACKUP_RX_INDEX), 0x0000
	LD (CPANEL_RX_INDEX), 0x0000

	CALR DELAY_6_TICKS

	LD A, 0x1f
	LD W, 0xda
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0x0000
	CALR DELAY_3000_LOOPS

	CALR LABEL_FC3FA9
	RET


LABEL_FC3FA9:
	LD A, 0x1f
	LD W, 0x1a
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0x0000
	CALR DELAY_3000_LOOPS

	LD A, 0x1d
	LD W, 0x00
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0x0000
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS

	LD A, 0xdd
	LD W, 0x03
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS

	LD (CPANEL_INDEX_FOR_LEDS), 0x0000
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS

	LD A, 0x1e
	LD W, 0x80
	CALR SEND_CMD_TO_CPANEL
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS
	CALR DELAY_3000_LOOPS

	EI, 0x06
	LD (INTES1), 0xff
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	AND (SC1MOD), 0xdf  ; RXE (bit 5) = 0: receive disable
	LD (INTCLR), 0x12 ; INTA Pin
	LD (INTEAB), 0x05
	LD (CPANEL_BACKUP_RX_INDEX), 0x0000
	LD (CPANEL_RX_INDEX), 0x0000
	OR (CPANEL_SERIAL_FLAGS_B), 0x01		; CP_Flags_B.0 = 1
	EI, 0x00
	RET


