CHECK_IF_WE_ARE_READY_TO_SEND_CMD_TO_CPANEL:
	LD (CPANEL_COUNTER_DOWN_FROM_200), 0xc8 ; =200

LABEL_FC437A:
	EI 0x06
	BIT 6, (PF)		; PF.6 = state of SCLK1 pin == 1 (resting at pull-up)
	JR Z LABEL_FC4394
	BIT 5, (PE)		; PE.5 = state of INTA pin == 0
	JR NZ LABEL_FC4394
	BIT 1, (CPANEL_SERIAL_FLAGS_A)
	JR NZ LABEL_FC4394
	BIT 0, (CPANEL_SERIAL_FLAGS_A)
	JR NZ LABEL_FC4394
	JR T LABEL_FC43A6

LABEL_FC4394:
	DEC 1 (CPANEL_COUNTER_DOWN_FROM_200)
	CP (CPANEL_COUNTER_DOWN_FROM_200), 0x00
	JR Z LABEL_FC43B0
	EI, 0x00
	CALR DELAY_1500_LOOPS
	JR T LABEL_FC437A

LABEL_FC43A6:
	; Only reaches here when CP_Flags_A.10 == 00, and I think only CPANEL_SERIAL_ROUTINE_0 sets that value...

	LD WA, (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS)
	CP WA, (CPANEL_INDEX_FOR_LEDS)
	JR NZ LABEL_FC4394

LABEL_FC43B0:
	EI, 0x06
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	LD (INTES1), 0xdd
	AND (SC1MOD), 0xdf  ; RXE (bit 5) = 0: receive disable
	OR (CPANEL_SERIAL_FLAGS_B), 0x80	; CP_Flags_B.7 = 1
	EI, 0x00
	RET


SEND_CMD_TO_CPANEL:
	EI, 0x06
	LD (CPANEL_INDEX_FOR_LEDS), 0x0000
	LD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), 0x0000
	LD (CPANEL_ARRAY__STATE_OF_LEDS), WA
	ADD (CPANEL_VAR_RELATED_TO_ARRAY_OF_LEDS), 0x0002
	OR (CPANEL_SERIAL_FLAGS_A), 0x02
	AND (CPANEL_SERIAL_FLAGS_A), 0xfe	; CP_Flags_A.10 = 2
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 0x04		; ROUTINE_1
	LD (BR1CR), 0x28 ; Internal Clock T8 (64/fc)
	                 ; Divide by 8
	                 ; fc = 16MHz, so fc/64/8 = 31250
	AND (PFFC_VALUE), 0xbf ; disable CPanel serial ckl
	LD A, (PFFC_VALUE)
	LD (PFFC), A
	AND (PF), 0xbf 		; PF bit 6: SCLK1 = 0
	OR (PFCR_VALUE), 0x40
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	LD (INTEAB), 0x07
	LD (INTCLR), 0x12 ; INTA Pin
	AND (SC1MOD), 0xdf  ; RXE (bit 5) = 0: CPanel receive disable
	AND (SC1CR), 0xfe  ; IOC (bit 0) = 0: I/O interface input clock select = Baud rate generator 
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	LD (INTES1), 0xdf
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (SC1BUF), A
	EI, 0x00
	NOP
	RET


INTA_HANDLER:					; fc442b
	LD (CPANEL_COUNTER_UP_TO_20), 0x00
	PUSH XWA
	CP (CPANEL_STATE_0_TO_17), 0x00
	JR NZ LABEL_FC4462

	AND (PFCR_VALUE), 0x9f
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	OR (SC1CR), 0x01	; IOC (bit 0) = 1: Set I/O interface input clock select to SCLK1 pin
	AND (SC1CR), 0xfd	; SCLKS (bit 1) = 0: Data transmit/receive at SCLK1 rising edge.
	LD (INTEAB), 0x05
	LD (INTES1), 0x0d
	OR (SC1MOD), 0x20  ; parity addition: enable
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 0x20;		ROUTINE_7
	OR (CPANEL_SERIAL_FLAGS_A), 0x01 ; CP_Flags_A.0 = 1
	JR T INTA_HANDLER_END

LABEL_FC4462:
	CP (CPANEL_RX_INDEX), 0x0000
	JR NZ LABEL_FC4470

	LD (CPANEL_RX_INDEX), 0x005c

LABEL_FC4470:
	DECW 1 (CPANEL_RX_INDEX)
	OR (CPANEL_SERIAL_FLAGS_B), 0x40	; CP_Flags_B.6 = 1  // UNUSED
	AND (CPANEL_SERIAL_FLAGS_A), 0xfd	; CP_Flags_A.1 = 0

INTA_HANDLER_END:      ; FC447E
	POP XWA
	LD (INTCLR), 0x12 ; INTA Pin
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	RETI


CPANEL_SERIAL_ROUTINES_LIST:		; FC4489
	dd CPANEL_SERIAL_ROUTINE_0 (offsets: 0x00)  // IDLE
	dd CPANEL_SERIAL_ROUTINE_1 (         0x04)  
	dd CPANEL_SERIAL_ROUTINE_2 (         0x08)
	dd CPANEL_SERIAL_ROUTINE_3 (         0x0c)
	dd CPANEL_SERIAL_ROUTINE_4 (         0x10)
	dd CPANEL_SERIAL_ROUTINE_5 (         0x14)
	dd CPANEL_SERIAL_ROUTINE_6 (         0x18)
	dd CPANEL_SERIAL_ROUTINE_0 (         0x1c)  
	dd CPANEL_SERIAL_ROUTINE_7 (         0x20)  // READ_BUTTONS_STATE_1
	dd CPANEL_SERIAL_ROUTINE_8 (         0x24)  // READ_BUTTONS_STATE_2
	dd CPANEL_SERIAL_ROUTINE_0 (         0x28)  // UNREACHABLE_STATE (?)


INTTX1_HANDLER:   ; FC44B5
	PUSH XWA
	PUSH XHL
	PUSH XIY
	LD L (CPANEL_SELECT_SERIAL_ROUTINE)
	XOR H H
	EXTZ XHL
	ADD XHL, CPANEL_SERIAL_ROUTINES_LIST
	LD XHL (XHL)
	JP T XHL


MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES:		; FC44CA
	POP XIY
	POP XHL
	POP XWA
	LD (INTCLR), 0x12 ; INTA Pin
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	RETI


INTRX1_HANDLER:   ; FC44D7
	PUSH XWA
	PUSH XHL
	PUSH XIY
	LD L (CPANEL_SELECT_SERIAL_ROUTINE)
	XOR H H
	EXTZ XHL
	ADD XHL, CPANEL_SERIAL_ROUTINES_LIST
