LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES:			; FC44EC
	POP XIY
	POP XHL
	POP XWA
	LD (INTCLR), 0x12 ; INTA Pin
	LD (INTCLR), 0x22 ; INTRX1: Serial receive 1
	LD (INTCLR), 0x23 ; INTTX1: Serial send 1
	RETI


CPANEL_SERIAL_ROUTINE_1:        ; FC44F9	// Start transmitting command to set LEDs on the control panel... (?)
	AND (PFCR_VALUE), 0xbf
	LD A, (PFCR_VALUE)
	LD (PFCR), A
	LD (BR1CR), 0x24 ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	LD (INTEAB), 0x07 ; INTTRA(TREGA): M=7
	LD (INTES1), 0xd0 ; INTTX1: M=5
	AND (SC1CR), 0xfe
	LD (SC1BUF), A
	INC 4 (CPANEL_SELECT_SERIAL_ROUTINE) ; next = ROUTINE_2
	MUL A, 0x01
	MUL A, 0x01
	BIT 6, (PF)		; PF.6 = state of SCLK1 pin
	JR NZ MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


						; If we receive a SCLK1 LOW, does it mean CPANEL is trying to spreak and we revert to IDLE state (ROUTINE_0) ?
	LD (CPANEL_STATE_0_TO_17), 0x00
	LD (CPANEL_SELECT_SERIAL_ROUTINE), 0x00 ; ROUTINE_0
	OR (CPANEL_SERIAL_FLAGS_B), 0x02	; CP_Flags_B.1 = 1  // UNUSED
	LD (INTEAB), 0x05
	LD (INTES1), 0xff
	LD (BR1CR), 0x24 ; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	AND (CPANEL_SERIAL_FLAGS_A), 0xfd ; CP_Flags_A.1 = 0
	JRL T MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


